package com.ecoriego.app.adapter;
import android.graphics.Color; import android.view.*; import android.widget.*; import androidx.annotation.NonNull; import androidx.recyclerview.widget.RecyclerView; import com.ecoriego.app.R; import com.ecoriego.app.model.Planta; import java.util.*;
public class PlantaAdapter extends RecyclerView.Adapter<PlantaAdapter.VH>{public interface Click{void go(Planta p);}private List<Planta> data;private Click click;private int rainChance;public PlantaAdapter(List<Planta>d,Click c){data=d;click=c;}public void setRainChance(int r){rainChance=r;notifyDataSetChanged();}public void setData(List<Planta>d){data=d;notifyDataSetChanged();}@NonNull public VH onCreateViewHolder(@NonNull ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_planta,p,false));}public void onBindViewHolder(@NonNull VH h,int pos){Planta p=data.get(pos);h.n.setText(p.getNombre());h.e.setText(p.getEspecie());h.u.setText("⌂ "+p.getUbicacion());h.r.setText("Riego cada "+p.getFrecuencia()+" días");boolean lluvia=rainChance>=60; h.s.setText(lluvia?"LLUVIA HOY":"VER DETALLE");h.itemView.setOnClickListener(v->click.go(p));}public int getItemCount(){return data.size();}static class VH extends RecyclerView.ViewHolder{TextView n,e,u,r,s;VH(View v){super(v);n=v.findViewById(R.id.tvNombre);e=v.findViewById(R.id.tvEspecie);u=v.findViewById(R.id.tvUbicacion);r=v.findViewById(R.id.tvRiego);s=v.findViewById(R.id.tvEstado);}}}
